css:
/* ===== Songdo Local overrides ===== */
:root{--sl-bg:#fbf8f3;--sl-paper:#fff;--sl-ink:#1f1d1a;--sl-muted:#6f6a62;--sl-line:#ebe5da;--sl-accent:#d9442b;--sl-accent-soft:#fde9e4;--sl-teal:#1f7a6d;--sl-teal-soft:#e2f2ef}
body{background:var(--sl-bg)!important;color:var(--sl-ink);font-family:Inter,"Noto Sans JP","Noto Sans KR",system-ui,sans-serif!important}
.centered-top-container,.bg-photo-container,.bg-photo-overlay,.centered-top-placeholder{display:none!important}
.sl-wrap{max-width:1120px;margin:0 auto;padding:0 20px;box-sizing:border-box}
.sl-head{background:var(--sl-paper);border-bottom:1px solid var(--sl-line);position:sticky;top:0;z-index:50}
.sl-nav{display:flex;align-items:center;gap:24px;height:64px}
.sl-logo{font:700 24px Fraunces,Georgia,serif;letter-spacing:-.5px;color:var(--sl-ink)!important;text-decoration:none!important}.sl-logo span{color:var(--sl-accent)}
.sl-menu{display:flex;gap:20px;font-weight:500;font-size:15px}.sl-menu a{color:var(--sl-muted)!important;text-decoration:none!important}.sl-menu a:hover{color:var(--sl-ink)!important}
.sl-lang{margin-left:auto;display:flex;gap:6px}
.sl-lang a{font-size:13px;padding:4px 10px;border:1px solid var(--sl-line);border-radius:99px;color:var(--sl-ink)!important;text-decoration:none!important}
.sl-lang a.on{background:var(--sl-ink);color:#fff!important;border-color:var(--sl-ink)}
.sl-banner{position:relative;background:#1f1d1a url('https://img.songdolocal.com/site/hero-central.jpg') center 40%/cover no-repeat;min-height:420px;display:flex;align-items:flex-end}
.sl-banner:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,14,20,.68) 0%,rgba(10,14,20,.38) 50%,rgba(10,14,20,.05) 100%)}
.sl-banner .sl-wrap{position:relative;width:100%}
.sl-banner .sl-credit{position:absolute;right:12px;bottom:6px;font-size:11px;color:rgba(255,255,255,.7)}
.sl-hero{padding:48px 0 34px;max-width:720px}
.sl-eyebrow{font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:#bff0e6}
.sl-hero h1{font:700 46px/1.1 Fraunces,Georgia,serif;margin:10px 0 14px;letter-spacing:-1px;color:#fff;text-shadow:0 2px 14px rgba(0,0,0,.35)}
.sl-hero p{color:rgba(255,255,255,.92);font-size:18px;margin:0 0 20px;text-shadow:0 1px 8px rgba(0,0,0,.4)}
.sl-below{padding-top:26px}
.sl-search{display:flex;background:var(--sl-paper);border:1px solid var(--sl-line);border-radius:14px;padding:6px}
.sl-search input{flex:1;border:0;font:inherit;padding:10px 12px;background:transparent;outline:none}
.sl-search button{border:0;background:var(--sl-accent);color:#fff;font-weight:600;border-radius:10px;padding:0 18px;cursor:pointer}
.sl-sec{font:700 22px Fraunces,Georgia,serif;margin:8px 0 12px;color:var(--sl-ink)}
.sl-areas{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:0 0 16px}
.sl-area{background:var(--sl-paper);border:1px solid var(--sl-line);border-radius:16px;padding:14px 16px;display:flex;flex-direction:column;gap:2px;text-decoration:none!important}
.sl-area b{font:600 17px Fraunces,Georgia,serif;color:var(--sl-ink)}.sl-area span{font-size:13px;color:var(--sl-muted)}
.sl-area:hover{border-color:var(--sl-accent);box-shadow:0 0 0 3px var(--sl-accent-soft)}
/* Essential 본문 쪽 톤 맞추기 */
.page_body .centered{max-width:1120px}
.post-title,.post-title a,h3.post-title a{font-family:Fraunces,Georgia,serif!important;color:var(--sl-ink)!important}
.post-outer-container,.post-outer,.widget.Blog .post{background:var(--sl-paper);border:1px solid var(--sl-line);border-radius:18px}
a{color:var(--sl-teal)}
.post-body{font-size:17px;line-height:1.75}
@media (max-width:860px){.sl-hero h1{font-size:32px}.sl-menu{display:none}.sl-areas{grid-template-columns:1fr 1fr}.sl-banner{min-height:340px}}
.sl-foot{border-top:1px solid var(--sl-line);background:var(--sl-paper);padding:22px 0 30px;margin-top:30px;font-size:13px;color:var(--sl-muted)}
.sl-foot nav{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:6px}.sl-foot a{color:var(--sl-ink)!important;text-decoration:none!important;font-weight:500}
